#!/usr/bin/env python3
"""Build the MT7921AU (MT7961) I/Q firmware iq_dma_v65 from your own linux-firmware copy.

  mt7961-iq-fw-v65.py [INPUT] [-o OUTPUT]

INPUT is linux-firmware's mediatek/WIFI_RAM_CODE_MT7961_1.bin (plain, .zst or
.xz); without it the script looks in /lib/firmware/mediatek/. It must be the
exact stock build 20260224110949 (sha256 b94217a951518a9c14095765f367bc5dd7698f2dc033941d6f18fc2ebd6a2ab9); anything else is
refused. The result (default ./WIFI_RAM_CODE_MT7961_1.bin) is checked against
sha256 1c740c6fe17d9e3ccc175aaef74e10e5187b2bc404ec49096f8a21f1e9714e4f before it is written.

The patch adds the I/Q stream code (hooks plus a patch body in the firmware's
code RAM) used by the mt7921-drv driver, and the version label "iq_dma_v65"
(shown as "WM Firmware Version" in the kernel log and by ethtool -i). Only
the changed bytes (2834 in 11 runs) are in this file.

Install (root), then reload the driver or replug the stick:

  install -m 644 WIFI_RAM_CODE_MT7961_1.bin /lib/firmware/mediatek/

The kernel tries the uncompressed name before .zst/.xz, so the stock file can
stay. If your distribution ships this firmware uncompressed, a linux-firmware
update overwrites the patched file; the driver then refuses to stream (it
checks the running firmware) until you patch again. If the firmware is also
in your initramfs, rebuild it. To go back to stock, delete the patched file.
"""
import argparse
import hashlib
import lzma
import os
import subprocess
import sys

NAME = "iq_dma_v65"
SIZE = 792036
IN_SHA256 = "b94217a951518a9c14095765f367bc5dd7698f2dc033941d6f18fc2ebd6a2ab9"
OUT_SHA256 = "1c740c6fe17d9e3ccc175aaef74e10e5187b2bc404ec49096f8a21f1e9714e4f"
FW_DIR = "/lib/firmware/mediatek"
FW_NAME = "WIFI_RAM_CODE_MT7961_1.bin"
# (file offset, new bytes as hex)
RUNS = [
    (0x0017a0, "44000002"),
    (0x00bdc2, "49026651"),
    (0x031ea6, "49013340"),
    (0x0476be, "84928006f101490084b8"),
    (0x0477c4, "49008688ea218120c81c490088fe"),
    (0x047866, "868f"),
    (0x047888, "49008612"),
    (0x057770, "9200920092009200920092009200"),
    (0x057fbc, ""),
    (0x058c0c, "75eb4075"),
    (0x0c15c7, "69715f646d615f763635"),
]


def load(path):
    if path.endswith(".zst"):
        try:
            return subprocess.run(["zstd", "-dc", path], check=True, capture_output=True).stdout
        except FileNotFoundError:
            sys.exit("%s: needs the zstd tool to decompress" % path)
    if path.endswith(".xz"):
        return lzma.open(path).read()
    with open(path, "rb") as f:
        return f.read()


def find_input():
    for ext in ("", ".zst", ".xz"):
        p = os.path.join(FW_DIR, FW_NAME + ext)
        if os.path.exists(p):
            data = load(p)
            if hashlib.sha256(data).hexdigest() == IN_SHA256:
                return p, data
    sys.exit("no stock %s (sha256 %s) in %s; give the file as INPUT" % (FW_NAME, IN_SHA256, FW_DIR))


def main():
    ap = argparse.ArgumentParser(description="Build the %s firmware from the stock linux-firmware file." % NAME)
    ap.add_argument("input", nargs="?", help="stock %s (plain, .zst or .xz); default: search %s" % (FW_NAME, FW_DIR))
    ap.add_argument("-o", "--output", default=FW_NAME, help="where to write the patched firmware (default ./%s)" % FW_NAME)
    ap.add_argument("--force", action="store_true", help="overwrite an existing output file")
    a = ap.parse_args()
    if a.input:
        src, data = a.input, load(a.input)
    else:
        src, data = find_input()
    digest = hashlib.sha256(data).hexdigest()
    if digest == OUT_SHA256:
        sys.exit("%s is already %s" % (src, NAME))
    if digest != IN_SHA256 or len(data) != SIZE:
        sys.exit("%s is not the stock firmware this patch is for:\n  sha256 %s\n  expected %s" % (src, digest, IN_SHA256))
    out = bytearray(data)
    for off, hexbytes in RUNS:
        b = bytes.fromhex(hexbytes)
        out[off:off + len(b)] = b
    if len(out) != SIZE or hashlib.sha256(out).hexdigest() != OUT_SHA256:
        sys.exit("internal error: result does not match %s" % OUT_SHA256)
    if os.path.exists(a.output) and not a.force:
        sys.exit("%s exists (use --force)" % a.output)
    if os.path.abspath(a.output) == os.path.abspath(src):
        sys.exit("refusing to overwrite the input")
    with open(a.output, "wb") as f:
        f.write(out)
    print("%s -> %s (%s, sha256 %s)" % (src, a.output, NAME, OUT_SHA256))
    print("install: install -m 644 %s %s/   then reload the driver or replug the stick" % (a.output, FW_DIR))


if __name__ == "__main__":
    main()
